#!/usr/bin/env python3
"""Close editorial group 1 without touching any other article group.

The script is intentionally idempotent. It adds the missing practical depth to
four named articles, preserves their existing metadata/FAQ/schema, and leaves
articles alone once the group marker is present.
"""
from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]
ART = ROOT / "website" / "articles"
MARK = "<!-- group1-closure-v1 -->"

ADDITIONS = {
"better-evening-home-lighting-without-overcomplicating-it.html": r'''<h2>12. Match lighting to the room's real weak spots</h2><p>After the first evening experiment, look for the places where the room still asks your eyes to work too hard. A dark corner beside a chair is different from glare on a television, and both are different from a kitchen work surface that is simply underlit. Treat each problem separately. If the corner is only used for walking, a modest low-level source may be enough. If someone reads there, a task lamp beside the chair is more appropriate.</p><p>This is also a good point to check reflections. A light that looks pleasant when you stand in the room can reflect from a television, glossy cabinet, framed glass or polished worktop when you sit down. Move the source a little to the side before increasing its output. Changing angle is often the cheapest way to improve comfort.</p><p>Keep a small note of what changed and why. That sounds excessive for a lamp, but it prevents the familiar cycle of changing several things at once and then not knowing which change actually helped. One controlled change per evening gives you useful evidence.</p><figure><img src="https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=1400&q=82" alt="Simple living area with practical low evening lighting" loading="lazy"><figcaption>Check the remaining weak spots after sunset instead of making the entire room brighter.</figcaption></figure><h2>13. Keep screens, pathways and faces comfortable</h2><p>Evening lighting has to work around more than furniture. Screens need a room that is not dominated by reflections, pathways need enough light to move safely and conversation areas benefit from light that reaches faces without creating a bright source directly behind someone. These are small details, but they explain why a room can feel wrong even when a light meter would suggest that it is bright enough.</p><p>For a television area, try a softer light to the side or behind the seating position rather than placing a bright lamp directly in the viewer's line of sight. For a hallway, use enough low-level light to identify steps, corners and obstacles without turning on every ceiling fixture. For a seating area, keep the brightest source out of the direct field of view.</p><p>If several people use the room differently, avoid designing the whole room around one person's preference. Give the person who reads a local task light and let the rest of the room stay comfortable for conversation or television. This keeps the system flexible without adding a complicated collection of scenes.</p><h2>14. Make changes in the safest order</h2><p>A sensible lighting project starts with placement, then glare, then brightness, and only after that technology. Check switches, cords and fixtures for damage before changing bulbs or adding equipment. Never leave a temporary lamp where its cable creates a trip hazard, and do not overload an outlet simply to add more light.</p><p>When replacing a bulb, follow the fixture's rating and the manufacturer's instructions. If a fixture becomes unusually hot, flickers persistently or shows damaged wiring, stop using it and have the problem assessed rather than trying to solve it with a brighter bulb. The U.S. Consumer Product Safety Commission provides household electrical safety information that is useful when a lighting problem turns into an electrical one: <a href="https://www.cpsc.gov/s3fs-public/513.pdf">CPSC electrical safety guidance</a>.</p><p>Once the physical setup is sound, repeat the same evening test: sit, read, walk, watch a screen and talk. If those ordinary activities feel comfortable without extra effort, the lighting is doing its job. You do not need to keep upgrading it simply because another device exists.</p>''',
"kitchen-counter-zone-that-stays-clear.html": r'''<h2>12. Build a landing rule for things that do not belong</h2><p>Even a well-organized counter will receive objects that are temporarily in transit. The important question is what happens next. Create one temporary landing rule for items that do not belong in the kitchen. A small basket near the edge of the room can hold a few things that need to leave, but it should be emptied during the reset rather than becoming a second storage system.</p><p>Be especially careful with mail, chargers, school items and tools. These categories are common because the kitchen is often the busiest room in the home. If they arrive there repeatedly, give them a destination outside the food-preparation path. The destination needs to be convenient enough that returning the item is easier than leaving it on the counter.</p><p>For groceries, use the same principle. Put cold and frozen items away first, then pantry items, then deal with packaging and reusable bags. A clear sequence reduces the chance that unloading a shopping trip turns the entire work surface into a temporary warehouse.</p><figure><img src="https://images.unsplash.com/photo-1556911220-bff31c812dba?auto=format&fit=crop&w=1400&q=82" alt="Practical kitchen counter with a small contained landing area" loading="lazy"><figcaption>A defined temporary landing area prevents unrelated household items from spreading across the worktop.</figcaption></figure><h2>13. Make the clear zone easy for other people to follow</h2><p>A counter system fails when only the person who designed it understands it. Keep the rules visible through placement rather than labels. If the cutting board always lives beside the prep zone, the next person can find it. If daily mugs have one shelf, they can be returned without asking. If paperwork has a tray in another room, the kitchen counter does not need to become the household inbox.</p><p>Explain only the few rules that matter: what can stay, what must move and where the recurring loose items go. Avoid creating a long list of organizing instructions. The system should be learnable by watching the room for a few days.</p><p>When someone repeatedly ignores one part of the system, treat that as feedback. The item may need a closer home or the chosen zone may be inconvenient. Adjust the environment before adding another reminder. Good organization removes decisions rather than multiplying them.</p><h2>14. Check food-preparation safety before optimizing appearance</h2><p>A clear counter is useful only if it remains a safe food-preparation surface. Keep cleaning products and unrelated household chemicals away from areas where food is prepared. Give raw-food preparation enough room to stay separate from ready-to-eat foods, and clean the work surface after handling raw meat or other foods that can contaminate it.</p><p>The U.S. Department of Agriculture's food-safety guidance is a useful reference when deciding how to arrange and clean a food-preparation zone: <a href="https://www.fsis.usda.gov/food-safety/safe-food-handling-and-preparation">USDA safe food handling guidance</a>. The practical point is simple: organization should make safe preparation easier, not merely make the counter look empty.</p><p>After one week, check the zone during the busiest meal you normally prepare. If you can place ingredients down, work comfortably, clean up and leave the center ready for tomorrow without moving unrelated objects, the system is doing what it needs to do. Stop there instead of organizing for organization’s sake.</p>''',
"quiet-entryway-storage.html": r'''<h2>12. Make the storage forgiving on bad days</h2><p>The real test of entryway storage is not a calm arrival with empty hands. It is the rainy evening when everyone comes home carrying bags, coats and groceries. Design for that moment. Hooks should be easy to reach, the shoe area should tolerate a few extra pairs and the landing zone should have enough room for normal daily variation without spilling into the walking path.</p><p>Forgiving storage does not mean making every container larger. It means allowing a small amount of mess without losing the basic function of the room. A hook can hold a coat and bag together for a short period. A shallow tray can accept today's keys and sunglasses. Seasonal overflow should still have a separate home so that one busy week does not permanently expand the entryway.</p><p>Notice which items become difficult first. Those are the places where the system needs more capacity or less friction. Solve the smallest recurring bottleneck rather than adding furniture to the whole wall.</p><figure><img src="https://images.unsplash.com/photo-1505693416388-ac5ce068fe85?auto=format&fit=crop&w=1400&q=82" alt="Simple practical entrance with a clear walking path and daily storage" loading="lazy"><figcaption>Good entryway storage still works on busy days because the walking path remains protected.</figcaption></figure><h2>13. Use labels only when they solve a real problem</h2><p>Labels can help a shared storage system, but too many labels can make a small entryway feel like an office. Label a container when people genuinely forget what belongs there, especially for seasonal accessories or household categories that are not obvious.</p><p>For everyday hooks and baskets, placement is usually enough. A coat hook does not need a label saying “coat.” A small box for dog-walking supplies may benefit from one clear label if several similar boxes exist elsewhere.</p><p>Keep the language ordinary. The goal is to make the next action obvious, not to create a catalog of the household. If a label needs an explanation, the storage category may be too broad.</p><h2>14. Protect the wall, floor and people using the entrance</h2><p>Before installing hooks or shelves, check the wall surface and the fixing method for the weight you expect them to carry. Follow the hardware manufacturer's instructions and use suitable fixings for the wall type. Keep sharp corners and protruding hardware out of the natural walking route, particularly in narrow entrances.</p><p>Also consider wet items. Coats, umbrellas and shoes may bring water into the entryway. A washable mat, a drip-safe place for umbrellas and a shoe area that can be cleaned are more useful than delicate decorative storage. The U.S. Consumer Product Safety Commission's home-safety resources are a useful reference when a storage project involves furniture stability or installation: <a href="https://www.cpsc.gov/Safety-Education">CPSC home-safety guidance</a>.</p><p>Once the physical setup is secure, test it with the household's real arrival routine. If people can enter, put things away and continue into the home without stopping to rearrange the storage, the system is quiet in the way that matters: it supports life instead of demanding attention.</p>''',
"simple-home-reset-that-prevents-weekend-chaos.html": r'''<h2>13. Use a different standard on genuinely busy days</h2><p>A routine that only works when everyone has energy is not a useful routine. Decide in advance what the minimum reset looks like on a difficult weekday. It might be dishes, rubbish, the main food surface and the entryway. Laundry and deeper tidying can wait if they are not going to create a problem tomorrow.</p><p>This minimum version protects the habit. You are not failing because you skipped a low-priority task; you are deliberately preserving the parts of the home that affect tomorrow. On a normal day, use the longer version. On a difficult day, use the short version and stop.</p><p>That distinction also reduces resentment. Household routines become easier to share when everyone understands that the goal is functional recovery, not an unrealistic standard of perfection every night.</p><figure><img src="https://images.unsplash.com/photo-1581578731548-c64695cc6952?auto=format&fit=crop&w=1400&q=82" alt="Practical short home reset focused on the most important daily tasks" loading="lazy"><figcaption>A short minimum reset keeps the routine alive when the day has gone badly.</figcaption></figure><h2>14. Prevent clutter at the point where it starts</h2><p>If the same pile appears every evening, move your attention upstream. A kitchen counter covered with mail may mean the mail has no first-stop location. Clothes on a chair may mean the laundry basket is too far away. Shoes by the sofa may mean the entryway storage is inconvenient. The repeated pile is evidence about the system.</p><p>Choose one recurring pile and ask what happens immediately before it appears. Change that moment rather than adding another cleanup step. A tray beside the door, a hook at the right height or a small bin beside a desk can prevent dozens of future resets.</p><p>This is the difference between maintenance and prevention. Maintenance clears what already happened. Prevention changes the environment so that the same mess is less likely to happen tomorrow.</p><h2>15. Keep deep cleaning separate from the daily reset</h2><p>Bathrooms, floors, windows, appliances and other deep-cleaning tasks deserve their own schedule. Mixing them into the daily reset makes the routine unpredictable and encourages people to postpone it because it feels too large.</p><p>Use the daily reset for function: clear the sink, restore high-traffic surfaces, move laundry forward, reset the entryway and identify one next action. Then use a weekly or monthly list for tasks that genuinely require more time. The two systems support each other without competing.</p><p>For a practical kitchen-focused reset, the USDA's household food-safety guidance is a useful reference for cleaning and safe food handling: <a href="https://www.fsis.usda.gov/food-safety">USDA food-safety resources</a>. The broader principle is to keep hygiene-critical work clear and specific rather than hiding it inside a vague instruction to “clean the house.”</p><p>After a week, measure the result by one question: did the reset make the next normal day easier? If yes, keep it. If a step repeatedly produces little benefit, remove it. A good reset becomes smaller and more reliable as the household learns what actually matters.</p>'''
}

def insert_before_faq(html: str, addition: str) -> str:
    if MARK in html:
        return html
    marker = '<h2>Frequently Asked Questions</h2>'
    if marker not in html:
        raise RuntimeError('FAQ heading not found')
    return html.replace(marker, MARK + addition + marker, 1)

changed = []
for name, addition in ADDITIONS.items():
    path = ART / name
    if not path.exists():
        raise SystemExit(f'Missing group 1 article: {path}')
    html = path.read_text(encoding='utf-8')
    new = insert_before_faq(html, addition)
    if new != html:
        path.write_text(new, encoding='utf-8')
        changed.append(name)

print('Group 1 closure:', 'changed ' + ', '.join(changed) if changed else 'already closed')
